package com.enterpriseflow.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="documents") public class Document {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;private String title;private String fileName;private String contentType;private String storagePath;@Column(columnDefinition="TEXT")private String extractedText;private String visibility;private boolean archived;@ManyToOne(fetch=FetchType.LAZY)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(nullable=false)private User owner;private Instant createdAt;protected Document(){}public Document(String t,String fn,String ct,String path,String text,String v,Project p,User o){title=t;fileName=fn;contentType=ct;storagePath=path;extractedText=text;visibility=v;project=p;owner=o;}@PrePersist void on(){createdAt=Instant.now();}public UUID getId(){return id;}public String getTitle(){return title;}public String getFileName(){return fileName;}public String getContentType(){return contentType;}public String getStoragePath(){return storagePath;}public String getExtractedText(){return extractedText;}public String getVisibility(){return visibility;}public boolean isArchived(){return archived;}public Project getProject(){return project;}public User getOwner(){return owner;}public Instant getCreatedAt(){return createdAt;}public void archive(){archived=true;}}
